#!/usr/bin/env python3
"""Generate js/assets.js: an explicit key -> path map of every asset.
The single-file builder rewrites the values in this map to data URIs."""
import pathlib, json

from PIL import Image

root = pathlib.Path(__file__).resolve().parent.parent

# Fallbacks for keys the page asks for that have no file of their own: each
# one stands in for another cut-out. They are declared here rather than left
# in the generated file by hand, because regenerating would silently drop them
# and the collage would come up short a few pieces with only a console warning.
# A real file of the right name always wins — these only fill gaps.
ALIASES = {}

files = sorted(p for p in (root / 'assets').rglob('*.webp'))
entries = []
for p in files:
    rel = p.relative_to(root).as_posix()          # assets/cut/eye.webp
    key = rel[len('assets/'):].rsplit('.', 1)[0]  # cut/eye
    entries.append((key, rel))

have = {k for k, _ in entries}
for key, rel in ALIASES.items():
    if key in have:
        continue                                  # the real cut-out exists
    if not (root / rel).exists():
        raise SystemExit(f'alias {key!r} points at missing file {rel!r}')
    entries.append((key, rel))
entries.sort()

lines = [
    '/* ============================================================',
    '   Asset registry — generated by tools/gen_assets.py',
    '   Keys are stable; values are rewritten to data: URIs by',
    '   tools/build_single.py when producing the single-file build.',
    '   ============================================================ */',
    '',
    'const ASSET = {',
]
for key, rel in entries:
    lines.append(f"  {json.dumps(key)}: {json.dumps(rel)},")
lines += [
    '};',
    '',
    '/* Aspect ratio (w/h) of every asset.',
    '   Both the letter tiles and the floating cut-outs reserve their boxes',
    '   from this before the image itself has loaded. Without it a box is laid',
    '   out at zero height, and anything positioned as a percentage inside it',
    '   — the coal\'s glow, the ash, the smoke — lands at the top and then drops',
    '   into place once the scan arrives. */',
    'const ASSET_AR = {',
]
for key, rel in entries:
    with Image.open(root / rel) as im:
        w, h = im.size
    lines.append(f"  {json.dumps(key)}: {w / h:.4f},")
lines += [
    '};',
    '',
    'function asset(key) {',
    '  const v = ASSET[key];',
    '  if (!v) console.warn("[assets] missing key:", key);',
    '  return v || "";',
    '}',
    '',
]
(root / 'js' / 'assets.js').write_text('\n'.join(lines), encoding='utf-8')
print(f'wrote js/assets.js with {len(entries)} assets')

# ---- report assets nothing on the page actually asks for -------------------
# They cost nothing to leave on disk but the single-file builder base64s every
# path it finds, so a cut-out dropped from the collage keeps shipping until
# somebody notices. This makes that visible instead.
import re
html = (root / 'index.html').read_text(encoding='utf-8')
sources = [root / f for f in re.findall(r'<script src="(js/[^"]+)"></script>', html)
           if f != 'js/assets.js']
blob = html + (root / 'css' / 'style.css').read_text(encoding='utf-8')
blob += '\n'.join(f.read_text(encoding='utf-8') for f in sources if f.exists())

def asked_for(key, rel):
    if key.startswith('letters/'):
        return True                      # built from a template string
    return any(q + key + q in blob for q in '"\'`') or rel in blob

live = {rel for key, rel in entries if asked_for(key, rel)}
dead = [(rel, (root / rel).stat().st_size) for key, rel in entries if rel not in live]
if dead:
    dead = sorted(set(dead), key=lambda x: -x[1])
    total = sum(s for _, s in dead)
    print(f'  ! {len(dead)} asset(s) nothing asks for, {total/1024:.0f} KB '
          f'({total*4/3/1024:.0f} KB once inlined):')
    for rel, size in dead[:8]:
        print(f'      {rel}  {size/1024:.1f} KB')
